def journey():
    steps = [('phone', 'Call or WhatsApp', 'Tell us your goal, current skills and when you can attend.'), ('users', 'Counselling on fit', 'We talk through the right course and starting level before you choose.'), ('board', 'Learn in the classroom', 'Offline sessions with a trainer in the room and practice in class.'), ('folder', 'Build your portfolio', 'Turn course exercises into work you can show and explain.'), ('brief', 'Career support', 'CV help, LinkedIn and Naukri profiles, mock interviews and placement assistance.')]
    li = ''.join(f'<li class="j-step" data-reveal="up" style="--d:{k*110}ms"><span class="j-dot icon-tile sm g-{["blue","cyan","violet","pink","green"][k]}">{icon(ic)}</span><span class="j-num">Step {k+1:02}</span><h3>{t}</h3><p>{b}</p></li>' for k, (ic, t, b) in enumerate(steps))
    return f'''<section class="section journey-section" id="journey"><div class="wrap">{heading('YOUR LEARNING JOURNEY','From first call<br>to <span class="grad-text">career-ready.</span>','A clear path from your first question to career support. The steps describe how we work with you, not a fixed timetable.', center=True)}<ol class="journey" data-progress>{li}</ol></div></section>'''

def why_offline():
    return f'''<section class="section why-section" id="why-offline"><div class="wrap">{heading('OFFLINE IS OUR USP','Why learn in a<br><span class="grad-text">real classroom?</span>','We teach only offline, at our centre in Bhopal. No recorded-video course, no learning alone at midnight. Just a trainer, a classroom and people learning alongside you.')}<div class="bento"><article class="bento-tile bento-hero tilt" data-reveal="zoom"><div class="card-glow" aria-hidden="true"></div><span class="pill pill-glow">100% offline classes</span><h3>A trainer in the room beats a video on pause.</h3><p>Ask your question when you are stuck, see it solved on screen and try it yourself straight away. That feedback loop is why we only teach in person.</p>{scene('class')}</article><article class="bento-tile tilt" data-reveal="up" style="--d:80ms"><div class="card-glow" aria-hidden="true"></div><span class="icon-tile g-cyan">{icon("chat")}</span><h3>Doubts cleared face to face</h3><p>No waiting on a forum or a support ticket. Ask in class.</p></article><article class="bento-tile tilt" data-reveal="up" style="--d:160ms"><div class="card-glow" aria-hidden="true"></div><span class="icon-tile g-violet">{icon("users")}</span><h3>Learn alongside others</h3><p>Classmates keep you going, and explaining work out loud builds confidence.</p></article><article class="bento-tile tilt" data-reveal="up" style="--d:240ms"><div class="card-glow" aria-hidden="true"></div><span class="icon-tile g-pink">{icon("clock")}</span><h3>A routine you will keep</h3><p>A set class time and place makes it easier to finish what you start.</p></article><article class="bento-tile tilt" data-reveal="up" style="--d:320ms"><div class="card-glow" aria-hidden="true"></div><span class="icon-tile g-blue">{icon("eye")}</span><h3>Visit before you decide</h3><p>See the centre and talk to us in person before choosing a course.</p></article><article class="bento-tile bento-wide tilt" data-reveal="up" style="--d:400ms"><div class="card-glow" aria-hidden="true"></div><div class="wide-row"><span class="icon-tile g-green">{icon("brief")}</span><div><h3>Career support in person, too</h3><p>CV help, LinkedIn and Naukri profile support, mock interviews, portfolio building and placement assistance, face to face.</p></div></div></article></div></div></section>'''

